-- Reproducible 2026/27 player seed for Retro Football Manager.
-- Requires db/schema.sql and db/seed-teams-2026-27.sql to be applied first.
-- Ratings are neutral game defaults, not official scouting ratings.
ON CONFLICT (id) DO UPDATE SET
  team_id=EXCLUDED.team_id,
  full_name=EXCLUDED.full_name,
  position=EXCLUDED.position,
  source_url=EXCLUDED.source_url,
  source_checked_at=EXCLUDED.source_checked_at;
